67	/// An error with some extra deduplication logic baked in.
68	///
69	/// Implemented by default for all relevant wgpu error types, though it might be worth
70	/// providing a more specialized implementation for errors that are too broad by nature:
71	/// e.g. a shader error cannot by deduplicated simply using the shader path.
72	trait DedupableError: Sized + std::error::Error + 'static {
73	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
74	        type_of_var(self).hash(state);
75	    }
76	
77	    fn eq(&self, rhs: &(dyn std::error::Error + Send + Sync + 'static)) -> bool {
78	        rhs.downcast_ref::<Self>().is_some()
79	    }
80	}
81	
82	/// E.g. to implement `DedupableError` for u32 + u64:
83	/// ```ignore
84	/// impl_trait![u32, u64];
85	/// ```
86	macro_rules! impl_trait {
87	    [$ty:ty, $($rest:ty),+ $(,)*] => {
88	        impl_trait![$ty];
89	        impl_trait![$($rest),+];
90	    };
91	    [$ty:ty $(,)*] => {
92	        impl DedupableError for $ty {}
93	    };
94	}
