163	impl std::hash::Hash for WgpuCoreWrappedContextError {
164	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
165	        // If we haven't set a debug label ourselves, the label is typically not stable across frames,
166	        // Since wgc fills in the generation counter.
167	        // Snip that part, starting with the last occurrence of -(.
168	        let label = if let Some(index) = self.0.label.find("-(") {
169	            &self.0.label[..index]
170	        } else {
171	            &self.0.label
172	        };
173	
174	        label.hash(state); // e.g. "composite_encoder"
175	        self.0.fn_ident.hash(state);
176	
177	        // try to downcast into something that implements `DedupableError`, and
178	        // then call `DedupableError::hash`.
179	        if try_downcast!(self.0.source => |inner| DedupableError::hash(inner, state)).is_none() {
180	            re_log::warn!(cause=?self.0.source, "unknown error cause");
181	        }
182	    }
183	}
