13	fn handle_async_error(
14	    backend_type: WgpuBackendType,
15	    resolve_callback: impl FnOnce(Option<wgpu::Error>) + 'static,
16	    error_future: impl std::future::Future<Output = Option<wgpu::Error>> + Send + 'static,
17	) {
18	    match backend_type {
19	        #[cfg(web)]
20	        WgpuBackendType::WebGpu => wasm_bindgen_futures::spawn_local(async move {
21	            resolve_callback(error_future.await);
22	        }),
23	        WgpuBackendType::WgpuCore => {
24	            if let Some(error) = now_or_never::now_or_never(error_future) {
25	                resolve_callback(error);
26	            } else {
27	                re_log::error_once!("Expected wgpu errors to be ready immediately when using any of the wgpu-core based (native & webgl) backends.");
28	            }
29	        }
30	    }
31	}
